const h = $input.item.json.headers || {};
const b = $input.item.json.body || {};
const auth = h['authorization'] || h['Authorization'] || '';
const token = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';
if (!token) return { json: { ok: false, status: 401, error: 'Missing session token' } };

// The page sends a data URL. Split it into the media type and payload Claude
// wants, and refuse anything that is not an image before it reaches the model.
const raw = String(b.image || '').trim();
if (!raw) return { json: { ok: false, status: 400, error: 'A photo is required' } };
const m = raw.match(/^data:(image\/(?:jpeg|png|webp|gif));base64,(.+)$/);
if (!m) return { json: { ok: false, status: 400,
  error: 'Unsupported image. Use a JPEG, PNG, WebP or GIF photo.' } };

// Claude's per-image ceiling is about 5MB; base64 inflates by ~4/3. The page
// resizes before sending, so this only catches a page that did not.
const b64 = m[2];
if (b64.length > 5 * 1024 * 1024) {
  return { json: { ok: false, status: 413,
    error: 'That photo is too large. Try again - the page should shrink it automatically.' } };
}

const cost = b.cost_cents != null ? parseInt(b.cost_cents, 10) : null;
return { json: {
  token: token,
  media_type: m[1],
  image_b64: b64,
  cost_cents: (cost && cost > 0) ? cost : null,
  hint: String(b.hint || '').slice(0, 300)
} };

const rows = $input.item.json;
const row = Array.isArray(rows) ? (rows[0] || null) : (rows && (rows.user_id || rows.id) ? rows : null);
if (!row) return { json: { ok: false, status: 401, error: 'Invalid or expired session' } };
if (row.user_role !== 'admin') return { json: { ok: false, status: 403, error: 'Admin access required' } };
return { json: Object.assign({ ok: true }, $('Extract').first().json) };

const r = $input.item.json || {};
if (r.error) {
  return { json: { ok: false, status: 502,
    error: 'Claude: ' + (r.error.message || r.error.type || 'request failed') } };
}
let text = '';
try { text = (r.content || []).map(function(c){ return c.text || ''; }).join('').trim(); }
catch (e) { text = ''; }
if (!text) return { json: { ok: false, status: 502, error: 'No listing came back. Try another photo.' } };

// Models sometimes fence JSON despite instructions. Take the outermost object.
const a = text.indexOf('{'), b = text.lastIndexOf('}');
if (a === -1 || b === -1) return { json: { ok: false, status: 502,
  error: 'Could not read the listing. Try again.' } };
let d;
try { d = JSON.parse(text.slice(a, b + 1)); }
catch (e) { return { json: { ok: false, status: 502, error: 'Could not read the listing. Try again.' } }; }

function cents(v){ const n = parseInt(v, 10); return (isNaN(n) || n < 0) ? null : n; }
const COND = ['new','open_box','used','as_is'];
const CLASS = ['SMALL','STANDARD','LARGE','OVERSIZED'];

const cost = $('Check Admin').first().json.cost_cents;
let reserve = cents(d.reserve_cents);
const notes = [];
if (d.notes) notes.push(String(d.notes));

// The model is told this, but a listing that sells below cost is the one
// mistake the seller cannot see until it has happened. Enforce it here too.
if (cost && (!reserve || reserve < cost)) {
  reserve = cost;
  notes.push('Reserve raised to your cost so this cannot sell at a loss.');
}

let buyNow = cents(d.buy_now_cents);
if (cost && buyNow && buyNow <= cost) {
  notes.push('Suggested Buy Now is at or below what you paid - raise it before listing.');
}

return { json: { ok: true, status: 200, draft: {
  title: String(d.title || '').slice(0, 200),
  description: String(d.description || '').slice(0, 2000),
  category: String(d.category || '').slice(0, 60),
  condition: COND.indexOf(d.condition) === -1 ? 'used' : d.condition,
  retail_cents: cents(d.retail_cents),
  buy_now_cents: buyNow,
  start_bid_cents: cents(d.start_bid_cents),
  reserve_cents: reserve,
  delivery_class: CLASS.indexOf(d.delivery_class) === -1 ? 'STANDARD' : d.delivery_class,
  sku: String(d.sku || '').slice(0, 40).toUpperCase(),
  seo_keywords: Array.isArray(d.seo_keywords) ? d.seo_keywords.slice(0, 8).map(String) : [],
  social_caption: String(d.social_caption || '').slice(0, 300),
  live_script: String(d.live_script || '').slice(0, 600),
  confidence: ['high','medium','low'].indexOf(d.confidence) === -1 ? 'low' : d.confidence,
  notes: notes.join(' ')
} } };
